solutionCode:
class Team(val number: Int, val name: String)

fun describe(team: Team): String {
    return "Team ${team.number}: ${team.name}"
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testTribots() {
        val team = Team(4215, "Tribots")
        Assert.assertEquals("Team 4215: Tribots", describe(team))
    }

    @Test
    fun testAnotherTeam() {
        val team = Team(254, "The Cheesy Poofs")
        Assert.assertEquals("Team 254: The Cheesy Poofs", describe(team))
    }

    @Test
    fun testTeamProperties() {
        val team = Team(4215, "Tribots")
        Assert.assertEquals(4215, team.number)
        Assert.assertEquals("Tribots", team.name)
    }
}
